'use strict';
const D=window.ATLAS;
let lang=localStorage.getItem('monato-lang')==='en'?'en':'ru', currentDetail=null, page=1, category='all', region='all', classSet='later', searchTimer;
const $=s=>document.querySelector(s), esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])), t=(ru,en)=>lang==='ru'?ru:en, name=x=>/^Item #\d+$/.test(x?.name?.en||'')?t('Неизвестный предмет','Unknown item'):x?.name?.[lang]||x?.name?.en||'—';
const L=new Map(D.locations.map(x=>[x.id,x])), N=new Map(D.npcs.map(x=>[x.id,x])), M=new Map(D.monsters.map(x=>[x.id,x])), Q=new Map(D.quests.map(x=>[x.id,x])), I=new Map(D.items.map(x=>[x.id,x])), S=new Map(D.skills.map(x=>[x.id,x]));
const title=(eyebrow,h,desc)=>`<div class="intro"><span class="eyebrow">${eyebrow}</span><h1>${h}</h1>${desc?`<p>${desc}</p>`:''}</div>`;
const badge=(text,cls='')=>`<span class="badge ${cls}">${esc(text)}</span>`;
const unknown=()=>`<span class="unknown-image">${t('Изображение в доступных ресурсах не найдено','No image found in available resources')}</span>`;
const img=(path,alt,cls='')=>path?`<img src="${esc(path)}" alt="${esc(alt)}" class="${cls}" loading="lazy">`:unknown();
const originalName=x=>lang==='ru'&&!/^Item #\d+$/.test(x.name.en)&&name(x)!==x.name.en?`<span class="translated-name">${esc(x.name.en)}</span>`:'';
const ruForms={'локаций':['локация','локации','локаций'],'связанных заданий':['связанное задание','связанных задания','связанных заданий'],'предметов в пуле':['предмет в пуле','предмета в пуле','предметов в пуле'],'видов монстров':['вид монстров','вида монстров','видов монстров'],'записей':['запись','записи','записей'],'заданий':['задание','задания','заданий'],'записей умений':['запись умений','записи умений','записей умений']};
const count=(n,ru,en)=>`${n} ${lang==='ru'?(ruForms[ru]?.[n%100>=11&&n%100<=14?2:n%10===1?0:n%10>=2&&n%10<=4?1:2]||ru):en}`;
const lidsHTML=ids=>`<div class="world-links">${ids.map(id=>L.has(id)?`<a href="#location/${id}">${esc(name(L.get(id)))}</a>`:'').join('')}</div>`;
const sourceDetail=(path,extra='')=>`<details class="details-source"><summary>${t('Источник и достоверность','Source & evidence')}</summary><p><code>${esc(path)}</code></p>${extra}</details>`;
const notice=(ru,en,gold=false)=>`<div class="notice${gold?' gold':''}">${t(ru,en)}</div>`;
const empty=(ru='По выбранным условиям ничего не найдено.',en='No records match these filters.')=>`<div class="empty">${t(ru,en)}</div>`;
const range=x=>x?x[0]===x[1]?String(x[0]):x.join('–'):'—';
const classInfo=[
 {id:'Novice',ru:'Новичок',role:['Первые шаги','First steps'],desc:['Начальный класс: бросок камня, удар мечом и преобразование маны в здоровье. Учебная цепочка знакомит с боем, алхимией и выбором профессии.','Starting class: a stone attack, a sword strike and mana-to-health conversion. The tutorial introduces combat, alchemy and profession choices.']},
 {id:'Templer',ru:'Храмовник',role:['Щит и защита','Shield & defense'],desc:['По извлечённым умениям — защитник со щитом: блок, провокация врагов, аура защиты и самолечение. В диалогах и каталоге навыков встречается написание Templar.','The extracted skills describe a shield defender: blocking, enemy taunts, defense auras and self healing. Dialogues and skill catalogs also use the spelling Templar.']},
 {id:'Hwarang',ru:'Воин Хваран',role:['Ближний бой','Melee combat'],desc:['По извлечённым умениям — физический боец: удары мечом, ударные волны, ослабление брони и усиление группы. Некоторые умения жертвуют HP или прочностью оружия.','The extracted skills describe a physical fighter: sword strikes, shockwaves, armor reduction and party support. Some skills sacrifice HP or weapon durability.']},
 {id:'Mage',ru:'Маг',role:['Заклинания и контроль','Magic & control'],desc:['Дальняя магия, ослабление противников, управление маной и атаки по области. Ранний и поздний наборы умений присутствуют в одном клиенте.','Ranged magic, enemy debuffs, mana management and area attacks. Early and later skill sets coexist in this client.']},
 {id:'Cleric',ru:'Целитель',role:['Лечение и поддержка','Healing & support'],desc:['Лечит героя и группу, воскрешает, усиливает характеристики и защиту. Также имеет атакующие заклинания и ослабление магического урона врага.','Heals players and parties, resurrects and improves attributes and defense. Also has offensive spells and an enemy magic damage debuff.']},
 {id:'Clown',ru:'Клоун',role:['Таблица класса','Class table'],desc:['Имя и таблица роста присутствуют в ConstTable. Отдельный подтверждённый набор умений и модель для этого класса в доступной поставке не установлены.','The name and growth table exist in ConstTable. A separate confirmed skill set and model have not been identified in the available client.']},
 {id:'Sheriff',ru:'Шериф',role:['Таблица класса','Class table'],desc:['Имя и таблица роста присутствуют в ConstTable. Данные не доказывают, что класс был доступен игрокам; отдельные умения и модель не подтверждены.','The name and growth table exist in ConstTable. This does not prove player availability; dedicated skills and a model are unconfirmed.']},
 {id:'Shaman',ru:'Шаман',role:['Таблица класса','Class table'],desc:['Имя и таблица роста присутствуют в ConstTable. Для доступного клиента не найдено отдельного подтверждённого набора умений и модели.','The name and growth table exist in ConstTable. A separate confirmed skill set and model have not been found for this client.']}
];
const className=c=>lang==='ru'?c.ru:c.id;
function entityCard(x,kind){const ismon=kind==='monster',qids=ismon?D.quests.filter(q=>q.objectives.some(o=>o.kind_raw===1&&o.type_id===x.id)).length:new Set(x.quests).size;return `<button class="entity" data-detail="${kind}" data-id="${x.id}"><div class="entity-image">${img(x.image,name(x))}${ismon&&x.boss?badge(t(x.bossKind==='boss'?'Босс':'Главарь',x.bossKind==='boss'?'Boss':'Chief'),'gold'):ismon&&!x.defined?badge(t('Нет определения','Unresolved'),'red'):''}</div><div class="entity-body"><h3>${esc(name(x))}</h3>${ismon?'':npcServiceBadges(x)}<p>${ismon?x.level!==null?`Lv ${x.level} · <span class="monster-card-hp">HP ${range(x.hp)}</span>`:t('Ссылка из старой расстановки TBK','Reference from an older TBK placement'):esc(npcSummary(x))}</p><div class="card-meta"><span>${count(x.locations.length,'локаций','locations')}</span><span>${ismon?bossLootSummary(x):count(new Set(x.quests).size,'связанных заданий','associated quests')}</span></div></div></button>`}
function locTypes(l,kind){return [...new Set(l.variants.flatMap(v=>v.objects.filter(x=>x.kind===kind).map(x=>x.id)))]}
function monsterLevelLabel(profile,withTitle=true){if(!profile?.monsterTypes)return t('Нет монстров','No monsters');const levels=profile.monsterLevelRange;if(!levels)return t('Уровни монстров неизвестны','Monster levels unknown');return (withTitle?t('Монстры · ур. ','Monsters · Lv '):'')+range(levels)+(profile.unknownMonsterLevels?' · '+t('часть уровней неизвестна','some levels unknown'):'')}
function worldVariantLabel(v,i){return (v.status==='connected'?t('Мир','World'):t('Архивный мир','Archived world'))+' '+(i+1)+' · '+monsterLevelLabel(v)}
function classEquipmentLabel(asset){return asset?.image&&asset.equipmentLevel?t(asset.id==='Novice'?'Улучшенный комплект новичка':'Улучшенный комплект · ур. '+asset.equipmentLevel,asset.id==='Novice'?'Fine novice equipment':'Fine equipment · Lv '+asset.equipmentLevel):t('Модель не подтверждена','Model unconfirmed')}

function locationCard(l){return `<a class="location-card" href="#location/${l.id}"><div class="location-cover">${img(l.cover||l.image,name(l))}${badge(l.archive?t('Архивная карта','Archived map'):l.region==='Старт'?t('Начало пути','First steps'):l.region)} </div><div class="location-body"><h3>${esc(name(l))}</h3>${locationAccessBadge(l)}<p>${monsterLevelLabel(l)} · ${l.maps[0]?.kind==='minimap'?t('Оригинальная миникарта','Original minimap'):t('Текстура поверхности','Surface texture')}</p><div class="card-meta"><span>${count(locTypes(l,'npc').length,'NPC','NPCs')}</span><span>${count(locTypes(l,'monster').length,'видов монстров','monster types')}</span></div></div></a>`}
function npcPortrait(id){const n=N.get(id);return n?.image?img(n.image,name(n),'quest-icon'):`<span class="quest-icon" style="display:grid;place-items:center;color:var(--cyan)">◇</span>`}
function questRow(q){return `<button class="quest-row" data-detail="quest" data-id="${q.id}">${npcPortrait(q.start)}<div><h3>${esc(name(q))}</h3><p>${esc(name(N.get(q.start)))}${q.end!==q.start?' · '+esc(name(N.get(q.end))):''} · Lv ${q.level.join('–')}${q.objectives.some(o=>o.kind_raw===1)?' · '+t('Бой','Combat'):''}</p></div><span class="quest-tail">${q.xp} XP</span></button>`}
function paginate(arr,render,size=36){const total=Math.max(1,Math.ceil(arr.length/size));page=Math.min(page,total);return arr.length?render(arr.slice((page-1)*size,page*size))+(total>1?`<div class="pagination"><button data-page="${page-1}" ${page===1?'disabled':''}>${t('Назад','Previous')}</button><span>${page} / ${total}</span><button data-page="${page+1}" ${page===total?'disabled':''}>${t('Далее','Next')}</button></div>`:''):empty()}
function filterChips(options,active,attr='category'){return `<div class="chips">${options.map(([id,ru,en])=>`<button class="chip ${id===active?'active':''}" data-${attr}="${id}">${t(ru,en)}</button>`).join('')}</div>`}
function locationFilter(){return `<select id="location-filter" aria-label="${t('Фильтр по локации','Filter by location')}"><option value="all">${t('Все локации','All locations')}</option>${D.locations.map(l=>`<option value="${l.id}" ${region===l.id?'selected':''}>${esc(name(l))}</option>`).join('')}</select>`}
function home(){const featured=[26,18,24].map(id=>L.get(String(id))).filter(Boolean);return `<section class="hero">${D.meta.hero?`<img class="hero-bg" src="${D.meta.hero}" alt="${t('Оригинальная иллюстрация Monato Esprit','Original Monato Esprit artwork')}">`:L.get('26')?.image?`<img class="hero-bg" src="${L.get('26').image}" alt="Moonrise Beach">`:''}<div class="hero-copy"><span class="eyebrow">${t('Двуязычный игровой атлас','A bilingual world atlas')}</span><h1>Monato Esprit</h1><p>${t('Локации и их жители, скрытые связи квестов, монстры и умения. Всё о Monato Esprit — в одном атласе.','Places and their inhabitants, connected quests, creatures and skills. Explore Monato Esprit in one atlas.')}</p><div class="actions"><a class="button primary" href="#world">${t('Исследовать мир','Explore the world')}</a><a class="button" href="#chain/500000001">${t('Путь новичка','The newcomer’s path')}</a></div></div><span class="hero-caption">${t('Monato Esprit · оригинальная иллюстрация клиента','Monato Esprit · original client artwork')}</span></section><div class="stats"><div class="stat"><strong>28</strong><span>${t('игровых карт<br>в архиве клиента','gameplay maps<br>in the client archive')}</span></div><div class="stat"><strong>193</strong><span>${t('определения NPC<br>в аудите диалогов','NPC definitions<br>in the dialogue audit')}</span></div><div class="stat"><strong>297</strong><span>${t('квестов<br>со связями и целями','quests with objectives<br>and dependencies')}</span></div><div class="stat"><strong>160</strong><span>${t('активных и пассивных<br>записей умений','active and passive<br>skill records')}</span></div></div><div class="section-heading"><h2>${t('Начните путешествие','Start your journey')}</h2><a class="text-link" href="#world">${t('Все локации','All locations')}</a></div><div class="grid">${featured.map(locationCard).join('')}</div><div class="feature-pair"><section class="feature"><span class="eyebrow">QUEST LINES</span><h2 style="margin-top:12px">${t('Одна встреча ведёт к другой','One encounter leads to the next')}</h2><p>${t('От первых уроков Вебера до подземелья Реи и знакомства с Исильдрой: проследите путь по исходным зависимостям заданий.','From Weber’s first lessons to Rhea’s dungeon and Isildra: follow the original quest dependencies.')}</p><div class="mini-path"><b>Weber</b><span class="path-line"></span><b>Jack</b><span class="path-line"></span><b>Hilly</b><span class="path-line"></span><b>Rhea</b></div><div class="npc-strip">${[50000,50003,50004,50001,50002].map(id=>`<button data-detail="npc" data-id="${id}" aria-label="${esc(name(N.get(id)))}">${img(N.get(id)?.image,name(N.get(id)))}<span>${esc(N.get(id)?.name.en)}</span></button>`).join('')}</div><div class="actions"><a class="text-link" href="#quests">${t('Открыть квестовые цепочки','Browse quest chains')}</a></div></section><section class="feature"><span class="eyebrow">CHARACTER CLASSES</span><h2 style="margin-top:12px">${t('Найдите свой стиль','Find your playstyle')}</h2><p>${t('Щит храмовника, клинок воина, магия и лечение. Сравните активные и пассивные умения, ранние и поздние наборы клиента.','A defender’s shield, a warrior’s blade, magic and healing. Explore active and passive skills and the client’s early and later sets.')}</p><div class="npc-strip">${classInfo.slice(1,5).map(c=>`<a href="#class/${c.id}" style="width:80px;height:110px">${img(D.classes?.find(x=>x.id===c.id)?.image,c.id)}</a>`).join('')}</div><div class="actions"><a class="text-link" href="#classes">${t('Смотреть классы и умения','Browse classes & skills')}</a></div></section></div>${notice('Атлас опирается на оригинальные файлы клиента. Наличие записи в каталоге не означает, что эта механика уже работает на локальном сервере.','The atlas is grounded in original client files. A catalog entry does not mean the mechanic is already supported by the local server.')}`}
function world(){let arr=D.locations.filter(l=>region==='all'||l.region===region);if(category==='connected')arr=arr.filter(l=>!l.archive);if(category==='archive')arr=arr.filter(l=>l.archive);return title('WORLD ATLAS',t('Локации мира','World locations'),t('Три региона, стартовые зоны и подземелья. Откройте карту, чтобы увидеть её жителей, добычу и квесты.','Three regions, starting areas and dungeons. Open a map to discover its inhabitants, loot and quests.'))+`<div class="toolbar">${filterChips([['all','Все карты','All maps'],['connected','Подключённые','Registered'],['archive','Архивные','Archived']],category)}<select id="region-filter" aria-label="${t('Регион','Region')}"><option value="all">${t('Все регионы','All regions')}</option>${[...new Set(D.locations.map(l=>l.region))].map(x=>`<option ${region===x?'selected':''}>${esc(x)}</option>`).join('')}</select><span class="result-count">${count(arr.length,'карт','maps')}</span></div><div class="grid">${arr.map(locationCard).join('')}</div>`+notice('28 игровых геометрий связаны с WRD; 27 подключены в GameRule. Архивная школа School_00 — отдельная карта. Варианты одного мира показаны внутри карточки локации.','28 gameplay geometries are referenced by WRD; 27 are registered in GameRule. Archived School_00 is a separate map. Variants of one world are listed on its location page.')}
function locationPage(id,query){const l=L.get(id);if(!l)return empty();let vi=Number(query.get('variant')??l.variants.findIndex(v=>v.status==='connected'));if(vi<0||vi>=l.variants.length)vi=0;const v=l.variants[vi],tab=query.get('tab')||'npcs';const npcIds=[...new Set(v.objects.filter(o=>o.kind==='npc').map(o=>o.id))],monIds=[...new Set(v.objects.filter(o=>o.kind==='monster').map(o=>o.id))],bosses=monIds.map(id=>M.get(id)).filter(x=>x?.boss),qs=D.quests.filter(q=>q.locations.includes(id));const map=l.maps.find(m=>m.kind==='minimap')||l.maps[0];let content='';if(tab==='npcs')content=`<div class="entity-grid">${npcIds.map(id=>N.get(id)).filter(Boolean).map(n=>entityCard(n,'npc')).join('')||empty(t('В этой версии мира в TBK нет NPC.','This world variant has no NPCs in TBK.'))}</div>`;if(tab==='monsters')content=`<div class="entity-grid">${monIds.map(id=>M.get(id)).filter(Boolean).map(m=>entityCard(m,'monster')).join('')||empty(t('В этой версии мира в TBK нет монстров.','This world variant has no monsters in TBK.'))}</div>`;if(tab==='bosses')content=`<div class="entity-grid">${bosses.map(m=>entityCard(m,'monster')).join('')||empty('В расстановке этого варианта подтверждённые боссы не найдены.','No confirmed bosses were found in this variant’s placement.')}</div>`;if(tab==='quests')content=notice('Задания связаны с локацией через NPC или тип цели. Совпадение типа монстра не доказывает, что квест выполняется только на этой карте.','Quests are associated through an NPC or objective type. A matching monster type does not prove that this is the only map where the quest can be completed.')+`<div class="quests-list">${qs.map(questRow).join('')||empty()}</div>`;const pins=v.objects.filter(o=>tab==='monsters'||tab==='bosses'?o.kind==='monster'&&(tab!=='bosses'||M.get(o.id)?.boss):o.kind==='npc').slice(0,140);return `<a class="back" href="#world">${t('Все локации','All locations')}</a>`+title(esc(l.region),esc(name(l))+originalName(l),'')+locationAccessPanel(l,v)+`<div class="zone-layout"><div>${map?`<div class="zone-map">${img(map.image,name(l))}${map.kind==='minimap'?pins.map((o,i)=>`<button class="map-pin ${o.kind==='monster'?'monster':''}" style="left:${Math.max(0,Math.min(100,o.pos[0]/v.extent[0]*100))}%;top:${Math.max(0,Math.min(100,(1-o.pos[2]/v.extent[1])*100))}%" data-detail="${o.kind}" data-id="${o.id}" title="${esc(name(o.kind==='monster'?M.get(o.id):N.get(o.id)))}" aria-label="${esc(name(o.kind==='monster'?M.get(o.id):N.get(o.id)))}">${o.kind==='npc'?'◇':'•'}</button>`).join(''):''}</div><p class="portrait-label">${t(map.kind==='minimap'?'Исходная миникарта · нажмите на жителя, чтобы открыть карточку':'Исходная текстура поверхности; это не навигационная миникарта',map.kind==='minimap'?'Original minimap · select an inhabitant to open its profile':'Original surface texture; this is not a navigational minimap')}</p><button class="quiet" data-lightbox="${map.image}" data-caption="${esc(name(l))} · ${esc(map.source)}">${t('Открыть изображение','Open image')}</button>`:empty('Исходная картинка карты отсутствует.','The source map image is missing.')}</div><div class="zone-aside"><div class="panel"><h3>${t('Паспорт локации','Location overview')}</h3><dl class="dl"><dt>${t('Уровни монстров','Monster levels')}</dt><dd>${monsterLevelLabel(v,false)}</dd><dt>NPC</dt><dd>${npcIds.length} ${t('типов','types')} / ${v.objects.filter(o=>o.kind==='npc').length} ${t('точек','placements')}</dd><dt>${t('Монстры','Monsters')}</dt><dd>${monIds.length} ${t('типов','types')}</dd><dt>${t('Боссы / главари','Bosses / chiefs')}</dt><dd>${bosses.length}</dd><dt>${t('Связанные квесты','Associated quests')}</dt><dd>${qs.length}</dd></dl></div>${l.variants.length>1?`<div class="panel"><label for="variant-filter">${t('Вариант мира','World variant')}</label><select id="variant-filter" style="margin-top:12px;width:100%">${l.variants.map((x,i)=>`<option value="${i}" ${i===vi?'selected':''}>${esc(worldVariantLabel(x,i))}</option>`).join('')}</select></div>`:''}<div class="panel"><h3>${t('Переходы из ACT','ACT destinations')}</h3>${v.transitions.length?lidsHTML([...new Set(v.transitions.map(x=>D.locations.find(l=>l.zones.includes(x.zone))?.id).filter(Boolean))]):`<p class="tagline">${t('Подтверждённые обычные назначения не найдены. Вход через NPC или инстанс может быть отдельной механикой.','No confirmed ordinary destinations found. NPC or instance entry can use separate mechanics.')}</p>`}<p class="tagline" style="margin-top:12px">${t('Это назначения действий; связь с конкретным порталом не полностью восстановлена.','These are action destinations; their exact portal triggers are not fully recovered.')}</p></div></div></div><div class="tabs" role="tablist">${[['npcs','NPC','NPCs',npcIds.length],['monsters','Монстры','Monsters',monIds.length],['bosses','Боссы','Bosses',bosses.length],['quests','Квесты','Quests',qs.length]].map(([key,ru,en,n])=>`<button class="tab ${tab===key?'active':''}" role="tab" aria-selected="${tab===key}" data-zone-tab="${key}">${t(ru,en)} <small>${n}</small></button>`).join('')}</div>${content}${sourceDetail(v.world,`<p>${esc(l.geometry)}</p><p>${t('Позиции — исходная статическая расстановка TBK. Динамическая популяция оригинального сервера неизвестна.','Positions are the original static TBK placements. The original server’s dynamic population is unknown.')}</p>`)}`}
function entities(kind,bossOnly=false){let arr=kind==='npc'?D.npcs:D.monsters;if(bossOnly)arr=arr.filter(x=>x.boss);if(region!=='all')arr=arr.filter(x=>x.locations.includes(region));if(category==='placed')arr=arr.filter(x=>x.locations.length);if(category==='image')arr=arr.filter(x=>x.image);if(category==='unresolved')arr=arr.filter(x=>!x.defined);return title(kind==='npc'?'INHABITANTS':bossOnly?'BOSS ARCHIVE':'BESTIARY',t(kind==='npc'?'Жители мира':bossOnly?'Боссы и главари':'Монстры мира',kind==='npc'?'World inhabitants':bossOnly?'Bosses & chiefs':'World creatures'),t(kind==='npc'?'Портреты, механики и роли в квестах. Откройте карточку, чтобы узнать, где найти NPC и с чем он помогает.':'Исходные модели, характеристики и кандидаты лута. Главари Chief и боссы Boss сохраняют различие из таблицы клиента.',kind==='npc'?'Portraits, mechanics and quest roles. Open a profile to find an NPC’s locations and services.':'Original models, attributes and loot candidates. Chief and Boss classifications preserve the client table’s distinction.'))+`<div class="toolbar">${filterChips([['all','Все записи','All records'],['placed','Есть на картах','Placed on maps'],['image','С изображением','With image'],...(kind==='monster'?[['unresolved','Без определения','Unresolved']]:[])],category)}${locationFilter()}<span class="result-count">${count(arr.length,'записей','records')}</span></div>`+paginate(arr,a=>`<div class="entity-grid">${a.map(x=>entityCard(x,kind)).join('')}</div>`)+(kind==='monster'?notice('Вероятности оригинального сервера не установлены. Показаны кандидаты из ItemDropTable, а принятые правила локального лута описаны отдельно.','Original server drop probabilities are unknown. ItemDropTable candidates are shown; adopted local drop rules are described separately.'):'')}
function questsPage(){let chains=D.chains.filter(c=>region==='all'||c.locations.includes(region));let quests=D.quests.filter(q=>region==='all'||q.locations.includes(region));if(category==='chains')chains=chains.filter(c=>c.quests.length>1);return title('QUEST CONNECTIONS',t('Истории, которые связывают мир','Stories that connect the world'),t('Полный каталог из 297 заданий. Проследите зависимость «предыдущий квест», участников, цели и переходы между локациями.','All 297 quests. Follow previous-quest dependencies, participants, objectives and connections across locations.'))+`<div class="toolbar">${filterChips([['all','Цепочки и отдельные задания','Chains & standalone quests'],['chains','Только цепочки','Chains only'],['catalog','Все задания','All quests']],category)}${locationFilter()}<span class="result-count">${category==='catalog'?quests.length:chains.length} ${t(category==='catalog'?'заданий':'историй',category==='catalog'?'quests':'stories')}</span></div>`+(category==='catalog'?paginate(quests,a=>`<div class="quests-list">${a.map(questRow).join('')}</div>`):paginate(chains,a=>`<div class="route-grid">${a.map(c=>`<a class="route-card" href="#chain/${c.id}">${badge(count(c.quests.length,'заданий','quests'),c.locations.length>1?'purple':'')}<h3>${esc(name(Q.get(c.root)))}</h3><p>${c.locations.map(id=>esc(name(L.get(id)))).join(' · ')||t('Позиции участников не найдены','Participant placements not found')}</p><p style="margin-top:12px">${c.quests.slice(0,3).map(x=>esc(name(Q.get(x.id)))).join(' / ')}${c.quests.length>3?' …':''}</p></a>`).join('')}</div>`))+notice('Связи previous извлечены из QuestData; циклов и отсутствующих предшественников нет. Несколько мест обитания одной цели показываются как возможные локации, а не обязательный маршрут.','Previous dependencies come from QuestData; no cycles or missing predecessors were found. Multiple locations for one objective are shown as possible locations, not a mandatory route.')}
function chainPage(id){const c=D.chains.find(x=>x.id===id);if(!c)return empty();let prevloc=null;return `<a class="back" href="#quests">${t('Все истории','All stories')}</a>`+title('QUEST LINE',esc(name(Q.get(c.root))),t('Каждый шаг сохраняет исходную зависимость. Карточка задания раскрывает цели, награды и участников.','Every step preserves its original dependency. A quest profile shows objectives, rewards and participants.'))+lidsHTML(c.locations)+`<div class="chain">${c.quests.map((node,index)=>{const q=Q.get(node.id),startloc=N.get(q.start)?.locations||[],endloc=N.get(q.end)?.locations||[];let cross='';const prev=Q.get(q.previous),prevLocations=prev?(N.get(prev.end)?.locations||[]):[];if(prevLocations.length&&startloc.length&&!prevLocations.some(id=>startloc.includes(id)))cross=`<div class="chain-cross">${t('Следующий этап — в другой локации','The next step moves to another location')}: ${prevLocations.map(id=>esc(name(L.get(id)))).join(' / ')} → ${startloc.map(id=>esc(name(L.get(id)))).join(' / ')}</div>`;if(q.start!==q.end&&startloc.length&&endloc.length&&!startloc.some(id=>endloc.includes(id)))cross=`<div class="chain-cross">${t('Между локациями','Across locations')}: ${startloc.map(id=>esc(name(L.get(id)))).join(' / ')} · ${endloc.map(id=>esc(name(L.get(id)))).join(' / ')}</div>`;if(q.id===500010001)cross+=`<div class="chain-cross">${t('Задание ведёт из Moonrise Beach в Newbie Training: Rabid Rabbit ×4, Yellow Rabbit ×3.','This quest leads from Moonrise Beach to Newbie Training: Rabid Rabbit ×4, Yellow Rabbit ×3.')}</div>`;return `<div class="chain-node"><p class="chain-region">${index+1}. ${startloc.map(id=>esc(name(L.get(id)))).join(' / ')||t('Позиция NPC не установлена','NPC placement unresolved')}${node.depth>0?' · '+t('После','After')+' '+esc(name(Q.get(q.previous))):''}</p>${cross}${questRow(q)}</div>`}).join('')}</div>`}
function classesPage(){return title('ARCHON CLASSES',t('Выберите свой путь','Choose your path'),t('Восемь имён классов в таблицах роста. Подтверждённые игровые наборы умений найдены у новичка и четырёх профессий.','Eight class names appear in growth tables. Confirmed player skill sets were found for the novice and four professions.'))+`<div class="class-grid">${classInfo.map(c=>`<a class="class-card" href="#class/${c.id}"><div class="entity-image">${img(D.classes?.find(x=>x.id===c.id)?.image,className(c))}</div><div class="entity-body">${badge(t(...c.role),'purple')}${D.classes?.find(x=>x.id===c.id)?.image?`<p class="class-equipment-label">${esc(classEquipmentLabel(D.classes.find(x=>x.id===c.id)))}</p>`:''}<h3 style="margin-top:12px">${esc(className(c))}</h3><p>${D.skills.filter(s=>s.family===c.id).length?count(D.skills.filter(s=>s.family===c.id).length,'записей умений','skill records'):t('Умения не установлены','Skill set unconfirmed')}</p></div></a>`).join('')}</div><div class="section-heading"><h2>${t('Общие и служебные умения','Shared & system skills')}</h2></div><div class="toolbar">${filterChips([['all','Знаки и сезоны','Signs & seasons'],['system','Служебные','System']],category)}</div>${category==='system'?`<div class="skill-grid">${D.skills.filter(s=>s.family==='system').map(skillCard).join('')}</div>`:birthCatalog()}${notice('Novice имеет пять строк роста, остальные классы — 40. Это не доказанный предел уровня персонажа. Clown, Sheriff и Shaman присутствуют в таблицах, но их доступность игрокам не подтверждена.','Novice has five growth rows; other classes have 40. These are not proven player level caps. Clown, Sheriff and Shaman appear in tables, but player availability is unconfirmed.')}`}
function skillCard(s){if(s.birth)return birthCard(s);return `<button class="skill" data-detail="skill" data-id="${s.id}">${s.image?img(s.image,name(s)):`<span class="unknown-image">${t('Нет иконки','No icon')}</span>`}<div><h3>${esc(name(s))}</h3><p>${esc(s.description[lang])}</p>${skillAccessCard(s)}<div class="card-meta"><span>${t(s.passive?'Пассивное':'Активное',s.passive?'Passive':'Active')}</span><span>${t('Рангов','Ranks')}: ${s.rank}</span><span>${s.mp} MP</span>${s.cooldown?`<span>${s.cooldown/1000} ${t('с восстановления','s cooldown')}</span>`:''}</div></div></button>`}
function classPage(id){const c=classInfo.find(x=>x.id===id);if(!c)return empty();const asset=D.classes?.find(x=>x.id===id);let skills=D.skills.filter(s=>s.family===id&&(id==='Novice'||s.generation===classSet));if(category==='active')skills=skills.filter(s=>!s.passive);if(category==='passive')skills=skills.filter(s=>s.passive);return `<a class="back" href="#classes">${t('Все классы','All classes')}</a><div class="class-hero">${img(asset?.image,className(c))}<div><span class="eyebrow">${t(...c.role)}</span><h1 style="margin-top:15px">${esc(className(c))}</h1>${lang==='ru'?`<p>${c.id}</p>`:''}<p>${t(...c.desc)}</p>${badge(classEquipmentLabel(asset),asset?.image?'purple':'muted')}</div></div>`+skillWindowNote(c)+(skills.length||D.skills.some(s=>s.family===id)?`<div class="toolbar">${id!=='Novice'?filterChips([['later','Действующий набор','Current set'],['early','Архивный набор','Archived set']],classSet,'set'):''}${filterChips([['all','Все умения','All skills'],['active','Активные','Active'],['passive','Пассивные','Passive']],category)}</div><div class="skill-grid">${skills.map(skillCard).join('')||empty()}</div>${notice('Описания отражают данные клиента. $a, $b, $t, $l, $h — исходные параметры; эффективные значения зависят от ранга и расчёта. Наличие умения не доказывает его реализацию на локальном сервере.','Descriptions reflect client data. $a, $b, $t, $l and $h are source parameters; effective values depend on rank and calculation. A listed skill is not proof of local server support.')}`:notice('Отдельный набор умений этого класса не найден. Заимствованные умения других профессий здесь не добавлены.','A separate skill set was not found for this class. Skills from other professions have not been assigned to it.',true))}
const mechanics=[
 {id:50000,title:['Проводники и журнал заданий','Guides & the quest journal'],body:['NPC открывает диалог и предлагает задания по уровню, маске класса и завершённому предшественнику. Ноль в EndNpc может означать сдачу у NPC выдачи.','NPC dialogue offers quests according to level, class mask and the completed predecessor. An EndNpc of zero can mean returning to the quest giver.'],items:[['Условия и цели показываются в карточке каждого задания.','Each quest profile lists requirements and objectives.'],['Связь квеста с локацией основана на исходных NPC и типах целей.','Location associations are grounded in source NPCs and objective types.']]},
 {id:50003,title:['Бой, умения и выбор награды','Combat, skills & reward choices'],body:['Джек ведёт через уроки боя и умений. Убийства засчитываются по нужному типу монстра, а разные цели имеют отдельные счётчики.','Jack guides combat and skill lessons. Kills match the required monster type, and separate objectives have separate counters.'],items:[['Skill Tutorial: Leek Mage ×2 и Leek Warrior ×1.','Skill Tutorial: Leek Mage ×2 and Leek Warrior ×1.'],['Исходная награда: Small Red Potion ×2 ИЛИ Small Blue Potion ×2. Это выбор, а не два гарантированных набора.','Source reward: Small Red Potion ×2 OR Small Blue Potion ×2. This is a choice, not two guaranteed rewards.']]},
 {id:50004,title:['Алхимия и рецепты','Alchemy & recipes'],body:['Хилли обучает рецептам и изготовлению. Свиток открывает рецепт; изготовление расходует материалы и выдаёт результат.','Hilly teaches recipes and crafting. A scroll unlocks the recipe; crafting consumes materials and produces the result.'],items:[['В ресурсах проверены 65 алхимических рецептов и 80 документов производства. Эти системы различаются.','65 alchemy recipes and 80 production blueprints were checked. These are separate systems.'],['Текущий восстановленный сервер поддерживает 65 алхимических и 80 производственных рецептов; в учебной цепочке используются 1000/1002.','The current restored server supports 65 alchemy and 80 production recipes; the tutorial uses 1000/1002.']]},
 {id:50002,title:['Зачарование и свойства предметов','Enchanting & item properties'],body:['Для зачарования нужны предмет и подходящий свиток; порошок необязателен. Проверяются ограничения, материалы и стоимость; свойство записывается в тот же предмет.','Enchanting uses equipment and a compatible scroll; powder is optional. Restrictions, materials and cost are checked, and the property is applied to the same item.'],items:[['Проверены 52 правила; текущая локальная конфигурация поддерживает все 52. Услуга у Джанго добавлена локальным патчем; исходное окно есть у Ирис, Линуса и Дрейка.','52 rules were checked; the current local configuration supports all 52. Django’s service is a local patch; Iris, Linus and Drake have the original menu.'],['В текущих правилах первое свойство заменяется. UID и прочность сохраняются.','Current rules replace the first property. Item UID and durability are retained.'],['Обычные свитки: +75 MaxHP или MaxMP; боссовый — +3 к пяти характеристикам.','Ordinary scrolls: +75 MaxHP or MaxMP; the chief scroll gives +3 to five attributes.']]},
 {id:50001,title:['Подземелья и возврат','Dungeons & returning'],body:['Рея предлагает Newbie Training. Вход в инстанс и возвращение используют отдельные действия. Кристалл внутри подземелья только восстанавливает HP/MP.','Rhea offers Newbie Training. Instance entry and return use separate actions. The dungeon crystal only restores HP/MP.'],items:[['Задание: Rabid Rabbit ×4, Yellow Rabbit ×3.','Quest: Rabid Rabbit ×4, Yellow Rabbit ×3.'],['Выход — отдельная исходная область, возвращающая в Moonrise Beach.','The exit is a separate source area returning to Moonrise Beach.'],['Автоматический таймер респавна dungeon в текущей политике не задан.','The current dungeon policy does not define an automatic respawn timer.']]},
 {id:50005,title:['MetaTIX, магазины и ремонт','MetaTIX, shops & repair'],body:['Белла объясняет MetaTIX. Амели, Питт, Баркер и Петра участвуют в учебной торговой цепочке. Исходные тарифы магазинов из клиента не восстановлены.','Bella introduces MetaTIX. Amelie, Pitt, Barker and Petra participate in the tutorial trading chain. Original shop tariffs cannot be recovered from the client alone.'],items:[['Во всех 1752 исходных ItemInfo цена равна нулю. Цены локальных магазинов заданы отдельно.','All 1,752 source ItemInfo prices are zero. Local shop prices are configured separately.'],['Локальная валюта хранится в кошельке героя. Внешний платёжный сервис не восстановлен.','Local currency is stored in each character’s wallet. The external payment service is not restored.'],['Ремонт и Refine рассматриваются отдельно; местный ремонт не уменьшает максимальную прочность.','Repair and Refine are distinct; local repair does not reduce maximum durability.']]},
 {id:60002,title:['Кристаллы восстановления','Recovery crystals'],body:['Красный кристалл восстанавливает HP, синий — MP, жёлтый — оба ресурса. Механика объекта и переход через портал должны проверяться раздельно.','Red crystals restore HP, blue restore MP, and yellow restore both. Object recovery and portal travel are separate mechanics.'],items:[['Принятое локальное правило: радиус 1000 игровых единиц; каждую секунду 10% максимальных HP/MP.','Adopted local rule: a 1,000-unit radius; 10% of maximum HP/MP every second.'],['Это настройка восстановления, а не доказанная константа оригинального сервера.','This is a restoration setting, not a proven original server constant.'],['Мёртвый герой не лечится. Кристалл Реи не телепортирует.','Dead characters are not healed. Rhea’s crystal does not teleport.']]},
 {id:50017,title:['Лут и инвентарь','Loot & inventory'],body:['Пул монстра показывает возможные предметы. Выбор добычи оригинальным сервером не восстановлен, поэтому сырые веса не показаны как проценты.','A monster’s pool lists possible items. Original server selection is not recovered, so raw weights are not presented as percentages.'],items:[['Moonrise/Rhea локально: независимые броски 40% на одну вещь и 40% на один свиток за убийство.','Local Moonrise/Rhea rule: independent 40% rolls for one equipment item and one scroll per kill.'],['Ресурсы заполняют оставшиеся места, максимум три разные строки; 2–3 при достаточном пуле.','Resources fill remaining slots, with up to three distinct rows; 2–3 when the pool permits.'],['Пустой пул не даёт предметов. У dungeon-главаря в исходном пуле нет свитков.','An empty pool produces no items. The dungeon chief’s original pool has no scrolls.']]}
];
function legacyMechanicsPage(){return title('NPC MECHANICS',t('Как работает мир','How the world works'),t('Сервисы NPC, прогресс героя и взаимодействие с предметами. Исходные данные и принятые локальные правила подписаны отдельно.','NPC services, character progression and item interactions. Source evidence and adopted local rules are labeled separately.'))+`<div class="mechanic-grid">${mechanics.map(m=>`<article class="mechanic">${N.get(m.id)?.image?img(N.get(m.id).image,name(N.get(m.id))):''}<span class="eyebrow">${esc(N.get(m.id)?.name.en||'WORLD OBJECT')}</span><h2 style="margin-top:12px">${t(...m.title)}</h2><p>${t(...m.body)}</p><ul>${m.items.map(x=>`<li>${t(...x)}</li>`).join('')}</ul>${N.has(m.id)?`<button class="text-link" data-detail="npc" data-id="${m.id}">${t('Карточка NPC','NPC profile')}</button>`:''}</article>`).join('')}</div>`}
function sourcesPage(){return title('SOURCES & COVERAGE',t('Основа атласа','The atlas foundation'),t('Срез исследования на 2 октября 2026 года. Атлас показывает содержимое оригинального клиента и отдельно описывает локальное восстановление.','Research snapshot dated 2 October 2026. The atlas presents the original client contents and separately describes the local restoration.'))+`<div class="sources"><section class="source"><h2>${t('Что подтверждено','What is grounded in evidence')}</h2><p>${t('39 WRD ссылаются на 28 игровых геометрий и два служебных мира. Три дополнительных ZNE не имеют ссылок из WRD. Каталог содержит 193 NPC и интерактивных объекта, включая проводников, торговцев и кристаллы.','39 WRD files reference 28 gameplay geometries and two service worlds. Three additional ZNE files are unreferenced. The catalog contains 193 NPCs and interactive objects, including guides, merchants and crystals.')}</p><p>${t('297 квестов, 177 связей previous и 160 записей умений. Все исходные миникарты и иконки извлечены из игровых архивов; текстура поверхности отмечена как BaseMap.','297 quests, 177 previous edges and 160 skill records. Original minimaps and icons come from the game archives; surface textures are identified as BaseMap.')}</p><p>${t('150 определений монстров в текущем GOP. В расстановках карт есть ещё 55 ID без совпадающего определения, имени и модели.','150 monster definitions in the current GOP. Map placements reference another 55 IDs without matching definitions, names or models.')}</p></section><section class="source"><h2>${t('Характеристики предметов · 03.10.2026','Item attributes · 03 Oct 2026')}</h2><p>${t('309 карточек экипировки сверены с полными исходными блоками ItemInfo. Добавлены эффекты 52 свитков зачарования, 113 рецептов и документов изготовления и действие свитка возвращения в Исильдру. Неустановленные параметры отмечены в карточках.','309 equipment profiles were matched against complete original ItemInfo blocks. Added effects for 52 enchantment scrolls, 113 recipes and production documents, and the Isildra Escape Scroll action. Unresolved fields are labeled in item details.')}</p><p>${t('Это параметры оригинального клиента, а не подтверждение доступности предмета или услуги на сервере. У рецептов исключены локальные настройки цены и успеха.','These are original client parameters; they do not establish item or service availability on a server. Local crafting price and success policies are excluded.')}</p></section><section class="source"><h2>${t('Крылья · полный каталог','Wings · complete catalog')}</h2><p>${t('11 видов крыльев и отдельная тестовая запись показаны без повторов. 23 исходных ID сохранены в сведениях об источниках. Каталог содержит 638 карточек предметов. Для всех крыльев проверены исходные блоки характеристик и иконки; выпадение привязано к точному ID через GOP → ItemDropTable. Текст подсказки крыльев индейки сохранён отдельно от подтверждённых числовых полей.','11 wing types and a separate test record are shown without duplicates. All 23 original IDs remain in source details. The catalog contains 638 item profiles. Every wing has verified original attribute blocks and icons; drops are linked by exact ID through GOP → ItemDropTable. Turkey Wings tooltip text is preserved separately from confirmed numeric fields.')}</p><a class="text-link" href="#wings">${t('Открыть крылья','Browse wings')}</a></section><section class="source"><h2>${t('Как читать изображения','How to read the images')}</h2><p>${t('Портреты NPC и иконки — исходные игровые изображения. Монстры, часть интерактивных объектов и основные классы показаны как рендеры исходных моделей в локальном просмотрщике. Освещение и камера отличаются от оригинального EXE.','NPC portraits and icons are original game images. Monsters, some interactive objects and primary classes are rendered from source models in a local viewer. Lighting and camera differ from the original EXE.')}</p><p>${t('Исторические детали моделей и отсутствующие части подписаны в карточках. У 142 предметов показаны две исходные иконки Ж/М с соответствующими именами ресурсов; выбор варианта клиентом не подтверждён. Для непроверенных типов монстров и трёх дополнительных классов изображения не выдумывались.','Historical model attachments and missing parts are noted in profiles. For 142 items, two matching original F/M icon variants are shown; the client’s selection of these variants remains unconfirmed. Unresolved monster types and three additional classes have no invented imagery.')}</p><p>${esc(D.meta.translationNote[lang])}</p></section><section class="source"><h2>${t('Границы данных','Evidence limits')}</h2><ul><li>${t('Расстановка TBK — статические точки, а не полная динамическая популяция оригинального сервера.','TBK is a static placement set, not the original server’s complete dynamic population.')}</li><li>${t('Назначения ACT не доказывают триггер конкретного портала.','An ACT destination does not prove a specific portal trigger.')}</li><li>${t('Веса лута сохранены как исходные числа; оригинальные вероятности неизвестны.','Loot weights remain raw source values; original probabilities are unknown.')}</li><li>${t('Условия типов целей 3 и 6, повторяемость, таймеры, группа и классовые переходы восстановлены не полностью.','Objective types 3 and 6, repeatability, timers, party credit and class transitions remain partially unresolved.')}</li><li>${t('Ранний и поздний наборы умений сосуществуют; выбор оригинального сервера неизвестен.','Early and later skill sets coexist; the original server’s selection is unknown.')}</li></ul></section><section class="source"><h2>${t('Файлы-источники','Source files')}</h2>${D.meta.sources.map(x=>`<p><code>${esc(x)}</code></p>`).join('')}<div class="actions"><a class="button" href="catalog.json" download="monato-esprit-catalog.json">${t('Скачать каталог JSON','Download JSON catalog')}</a></div></section></div>`}
function normalized(s){return String(s).toLocaleLowerCase().normalize('NFKC').trim()}
function match(x,s){return normalized([x.id,x.wing?.sourceIds?.join(' '),x.name.ru,x.name.en,x.description?.ru,x.description?.en].join(' ')).includes(s)}
function searchPage(query){const s=normalized(query), groups=[['Локации','Locations',D.locations.filter(x=>match(x,s)),a=>`<div class="grid">${a.map(locationCard).join('')}</div>`],['NPC','NPCs',D.npcs.filter(x=>match(x,s)),a=>`<div class="entity-grid">${a.map(x=>entityCard(x,'npc')).join('')}</div>`],['Монстры','Monsters',D.monsters.filter(x=>match(x,s)),a=>`<div class="entity-grid">${a.map(x=>entityCard(x,'monster')).join('')}</div>`],['Квесты','Quests',D.quests.filter(x=>match(x,s)),a=>`<div class="quests-list">${a.map(questRow).join('')}</div>`],['Умения','Skills',D.skills.filter(x=>match(x,s)),a=>`<div class="skill-grid">${a.map(skillCard).join('')}</div>`],['Предметы','Items',D.items.filter(x=>match(x,s)),a=>`<div class="loot-grid">${a.map(x=>itemHTML(x)).join('')}</div>`]];return title('ATLAS SEARCH',t('Поиск по атласу','Search the atlas'),`${t('Запрос','Query')}: “${esc(query)}”`)+(s?groups.filter(x=>x[2].length).map(([ru,en,a,render])=>`<section class="search-result-section"><div class="section-heading"><h2>${t(ru,en)}</h2><span class="result-count">${a.length}</span></div>${render(a.slice(0,30))}${a.length>30?`<p class="tagline" style="margin-top:16px">${t('Показаны первые 30 совпадений. Уточните запрос.','Showing the first 30 matches. Refine the query.')}</p>`:''}</section>`).join('')||empty():empty('Введите название на русском или английском.','Enter a Russian or English name.'))}
function itemImages(item){return item.imageVariants?.length?'<span class="item-variants">'+item.imageVariants.map(v=>'<span>'+img(v.image,name(item))+'<small>'+t(v.gender==='female'?'Ж':'М',v.gender==='female'?'F':'M')+'</small></span>').join('')+'</span>':item.image?img(item.image,name(item)):'<span>◇</span>'}
function itemHTML(item,countValue,rewardKind){if(typeof item==='number')item=I.get(wingCanonicalId(item));if(!item)return '';return `<button class="item" data-detail="item" data-id="${item.id}">${itemImages(item)}<span>${esc(name(item))}${countValue?` ×${countValue}`:''}${recoverySummary(item)}${rewardKind!==undefined?`<small>${t(rewardKind?'На выбор':'Гарантированная награда',rewardKind?'Reward choice':'Guaranteed reward')}</small>`:''}</span></button>`}
function objectiveHTML(o){const kind=o.kind_raw,id=o.type_id,n=kind===0?N.get(id):kind===1?M.get(id):I.get(id);let label=kind===0?t('Поговорить с','Talk to'):kind===1?t('Победить','Defeat'):kind===2?t('Собрать / иметь','Collect / possess'):kind===3?t('Квестовый предмет','Quest item'):t('Особое условие','Special condition');return `<li>${label}: ${n?`<button class="text-link" data-detail="${kind===0?'npc':kind===1?'monster':'item'}" data-id="${id}">${esc(name(n))}</button>`:t('Неустановленная цель','Unresolved objective')}${o.required_count?' ×'+o.required_count:''}${kind===3&&o.extra_raw?` · ${t('Связанный NPC','Associated NPC')} ${esc(name(N.get(o.extra_raw)))}`:''}${[3,6].includes(kind)?` <span class="tagline">(${t('полная серверная семантика не восстановлена','complete server semantics unresolved')})</span>`:''}</li>`}
function detail(kind,id){id=kind==='item'?wingCanonicalId(id):Number(id);const x=({npc:N,monster:M,quest:Q,skill:S,item:I}[kind])?.get(id);if(!x)return;currentDetail={kind,id};let head='',body='';if(kind==='npc'||kind==='monster'){head=`<div class="detail-head">${x.image?img(x.image,name(x)):unknown()}<div><span class="eyebrow">${kind==='npc'?'NPC':x.boss?t('Босс / главарь','Boss / chief'):'BESTIARY'}${kind==='npc'||x.boss?'':' · #'+id}</span><h2>${esc(name(x))}</h2>${originalName(x)}<p>${kind==='npc'?esc(npcSummary(x)):x.defined?`Lv ${x.level} · HP ${range(x.hp)}`:t('Этот ID найден в TBK, но отсутствует в таблице определений текущего клиента. Имя, модель и лут не установлены.','This ID appears in TBK but is absent from the current client’s definition table. Name, model and loot are unresolved.')}</p></div></div>`;body+=`<section class="detail-section"><h3>${t('Где найти','Where to find')}</h3>${x.locations.length?lidsHTML(x.locations):`<p>${t('Определение найдено, но подтверждённой позиции в каталоге WRD/TBK нет.','Definition found, but no confirmed position in the WRD/TBK catalog.')}</p>`}</section>`;if(kind==='monster'&&x.defined){body+=`${monsterAttributes(x)}${x.boss?bossLootHTML(x):`<section class="detail-section"><h3>${t('Возможная добыча','Loot candidates')} · ${x.loot.length}</h3>${x.loot.length?`<div class="loot-grid">${x.loot.map(id=>itemHTML(id)).join('')}</div>`:`<p>${t('В связанных исходных таблицах пул пуст.','The associated source tables contain an empty pool.')}</p>`}${notice('Список кандидатов не означает, что все предметы выпадают одновременно. Исходные вероятности не восстановлены.','A candidate list does not mean all items drop together. Original probabilities are unresolved.')}</section>`}`;if(x.localLoot)body+=`<section class="detail-section"><h3>${t('Пул текущего локального сервера','Current local server pool')}</h3>${Object.entries(x.localLoot).map(([k,ids])=>`<p>${t(({equipment:'Экипировка',scroll:'Свитки',resource:'Ресурсы'})[k]||k,({equipment:'Equipment',scroll:'Scrolls',resource:'Resources'})[k]||k)}: ${ids.map(id=>esc(name(I.get(id)))||'#'+id).join(', ')||t('пусто','empty')}</p>`).join('')}<a class="text-link" href="#mechanics">${t('Правила локального лута','Local loot rules')}</a></section>`;if(x.renderNotes?.length)body+=notice(x.renderNotes.map(n=>esc(n.ru)).join(' '),x.renderNotes.map(n=>esc(n.en)).join(' '),true)}if(kind==='npc'){body+=npcServicesDetail(x);const mechanic=mechanics.find(m=>m.id===id)||(['Amelie','Pitt','Barker','Petra'].includes(x.name.en)?mechanics.find(m=>m.id===50005):null);if(mechanic)body+=`<section class="detail-section"><h3>${t(...mechanic.title)}</h3><p>${t(...mechanic.body)}</p><ul class="plain-list">${mechanic.items.map(v=>`<li>${t(...v)}</li>`).join('')}</ul><a class="text-link" href="#mechanics">${t('Все механики NPC','All NPC mechanics')}</a></section>`;if(x.imageKind==='model')body+=`<p class="tagline">${t('Изображение получено из исходной модели. Для кристаллов включена цветная EFF-геометрия; частицы и анимация не отображаются.','Rendered from the original model. Crystal images include colored EFF geometry; particles and animation are not shown.')}</p>`}const quests=kind==='npc'?[...new Set(x.quests)].map(id=>Q.get(id)).filter(Boolean):D.quests.filter(q=>q.objectives.some(o=>o.kind_raw===1&&o.type_id===id));if(quests.length)body+=`<section class="detail-section"><h3>${t('Связанные задания','Associated quests')} · ${quests.length}</h3>${quests.map(questRow).join('')}</section>`;if(kind==='npc'&&x.greeting?.length)body+=`<details class="details-source"><summary>${t('Исходное приветствие · English','Original greeting · English')}</summary><p>${esc(x.greeting.join('\n')).replace(/\n/g,'<br>')}</p></details>`;body+=sourceDetail(kind==='npc'?x.source||'Data/objectpropertyset.gop':'Data/objectpropertyset.gop → ItemDropTable.iif',`<p>${esc(x.model||'')}</p>${x.sourceOffset?`<p>GOP offset: ${x.sourceOffset}</p>`:''}`)}
if(kind==='quest'){head=`<div class="detail-head">${N.get(x.start)?.image?img(N.get(x.start).image,name(N.get(x.start))):unknown()}<div><span class="eyebrow">QUEST · #${id}</span><h2>${esc(name(x))}</h2>${originalName(x)}<p>Lv ${x.level.join('–')} · ${x.xp} XP · ${t('Маска классов','Class mask')} 0x${x.classMask.toString(16).toUpperCase()}</p></div></div>`;const chain=D.chains.find(c=>c.quests.some(q=>q.id===id));body+=`<div class="mini-path"><button class="text-link" data-detail="npc" data-id="${x.start}">${esc(name(N.get(x.start)))}</button><span class="path-line"></span><button class="text-link" data-detail="npc" data-id="${x.end}">${esc(name(N.get(x.end)))}</button></div><section class="detail-section"><h3>${t('Зависимость','Prerequisite')}</h3>${x.previous?`<button class="text-link" data-detail="quest" data-id="${x.previous}">${esc(name(Q.get(x.previous)))}</button>`:`<p>${t('Нет предыдущего квеста. Остальные ограничения сохраняются.','No previous quest. Other restrictions still apply.')}</p>`}${chain?`<div class="actions"><a class="button" href="#chain/${chain.id}">${t('Вся цепочка','Full quest chain')}</a></div>`:''}</section><section class="detail-section"><h3>${t('Цели','Objectives')}</h3><ul class="plain-list">${x.objectives.map(objectiveHTML).join('')}</ul></section><section class="detail-section"><h3>${t('Награды','Rewards')}</h3><p>${x.xp} XP${x.money?' · '+x.money+' '+t('валюты (поле таблицы)','currency (table field)'):''}</p>${x.choices?notice(`Выберите ${x.choices} вариант(а) награды.`, `Choose ${x.choices} reward option(s).`,true):''}<div class="loot-grid">${x.rewards.map(r=>itemHTML(I.get(r.id??r.item_id),r.count??r.quantity,r.selectable)).join('')}</div></section><section class="detail-section"><h3>${t('Связанные локации','Associated locations')}</h3>${lidsHTML(x.locations)}</section>${x.dialogue.length?`<details class="details-source"><summary>${t('Исходные диалоги · English','Original dialogue · English')}</summary><div class="dialogue-text">${x.dialogue.map(d=>`<p><strong>${esc(d.phase)}</strong><br>${esc(d.text)}</p>`).join('')}</div></details>`:''}${sourceDetail('Data/QuestData.dat',`<p>${t('Типы целей 3/6, таймеры, повторяемость и серверная достижимость частично не установлены. Поле save не гарантирует повторяемость.','Objective types 3/6, timers, repeatability and server reachability remain partly unresolved. The save flag does not guarantee repeatability.')}</p>`)}`}
if(kind==='skill'){head=`<div class="detail-head">${x.image?img(x.image,name(x)):unknown()}<div><span class="eyebrow">${x.birth?t(x.birth.group==='sign'?'Знак зодиака':'Сезон',x.birth.group==='sign'?'Zodiac sign':'Season'):x.family+' · #'+id}</span><h2>${esc(name(x))}</h2>${originalName(x)}<p>${esc(x.description[lang])}</p></div></div>`;body+=x.birth?birthDetails(x):skillAccessDetails(x)+skillMechanicsDetails(x)+`<section class="detail-section"><dl class="dl"><dt>${t('Тип','Type')}</dt><dd>${t(x.passive?'Пассивное':'Активное',x.passive?'Passive':'Active')}</dd><dt>${t('Максимальный ранг','Maximum rank')}</dt><dd>${x.rank}</dd><dt>${t('Базовая стоимость MP','Base MP cost')}</dt><dd>${x.mp}</dd><dt>${t('Прирост MP','MP increment')}</dt><dd>${x.mpIncrement}</dd><dt>${t('Фаза анимации','Action phase')}</dt><dd>${x.casting/1000} s</dd><dt>${t('Восстановление','Cooldown')}</dt><dd>${x.cooldown/1000} s</dd><dt>${t('Дальность · единицы клиента','Range · client units')}</dt><dd>${x.range}</dd><dt>${t('Маска класса','Class mask')}</dt><dd>0x${x.classMask.toString(16)}</dd><dt>${t('Маска оружия','Weapon mask')}</dt><dd>0x${x.weaponMask.toString(16)}</dd></dl></section><section class="detail-section"><h3>${t('Исходное описание · English','Original description')}</h3><p>${esc(x.originalDescription?.en||x.description.en)}</p>${notice('Числа выше — поля таблицы, а не рассчитанная эффективность. Условия открытия и стоимость рангов показаны выше с отдельными пометками оригинала и восстановленного сервера.','The numbers above are table fields, not calculated effectiveness. Unlock requirements and rank costs are shown above, separately labeled for the original game and restored server.')}</section>${sourceDetail('Data/Skill/skill.dat',`<p>${esc(x.source)}</p>`)}`}
if(kind==='item'){head=`<div class="detail-head">${x.image?img(x.image,name(x)):unknown()}<div><span class="eyebrow">${t('Предмет','Item')}</span><h2>${esc(name(x))}</h2>${originalName(x)}</div></div>`;body+=itemCharacteristics(x)+itemAppearance(x);const mons=D.monsters.filter(m=>m.loot.includes(id)),qs=D.quests.filter(q=>q.rewards.some(r=>(r.id??r.item_id)===id)||q.objectives.some(o=>[2,3].includes(o.kind_raw)&&o.type_id===id));body+=`${x.wing?wingLoot(x):`<section class="detail-section"><h3>${t('Возможный лут с монстров','Monster loot candidates')}</h3><div class="world-links">${mons.map(m=>`<button class="text-link" data-detail="monster" data-id="${m.id}">${esc(name(m))}</button>`).join(' · ')||t('Не найден в связанных таблицах монстров.','Not found in associated monster tables.')}</div></section>`}${qs.length?`<section class="detail-section"><h3>${t('Квесты','Quests')}</h3>${qs.map(questRow).join('')}</section>`:''}${x.imageVariants?.length?`<section class="detail-section"><h3>${t('Исходные варианты иконки','Original icon variants')}</h3><div class="gender-icons">${x.imageVariants.map(v=>`<figure>${img(v.image,name(x))}<figcaption>${t(v.gender==='female'?'Женский вариант':'Мужской вариант',v.gender==='female'?'Female variant':'Male variant')}</figcaption></figure>`).join('')}</div>${notice('В архиве найдены оригинальные варианты с суффиксами (f) и (m). Общий DDS-путь из ItemInfo отсутствует; механизм выбора иконки клиентом не подтверждён.','Original (f) and (m) variants were found in the archive. The generic ItemInfo DDS path is absent; the client’s icon selection mechanism is unconfirmed.')}</section>`:''}${sourceDetail('Data/iteminfo.iif',`<p>${esc(x.source)}</p>${x.imageVariants?.map(v=>`<p>${esc(v.source)}</p>`).join('')||''}`)}`}
$('#detail-content').innerHTML=head+body;if(!$('#detail').open)$('#detail').showModal();$('#detail').scrollTop=0}
function route(){const raw=location.hash.slice(1)||'home', [path,qs]=raw.split('?'),parts=path.split('/');return {view:parts[0],id:parts[1],query:new URLSearchParams(qs||'')}}
const navItems=[['home','⌂','Обзор','Overview',''],['items','▱','Предметы','Items',String(D.items.length)],['wings','⋈','Крылья','Wings','12'],['world','◎','Локации','Locations','28'],['npcs','♙','NPC и услуги','NPCs & services','193'],['bestiary','♧','Монстры и лут','Monsters & loot','150'],['bosses','♜','Боссы и главари','Bosses & chiefs',''],['story','☷','Сюжет и путь героя','Story & journey',''],['quests','◇','Квестовые цепочки','Quest chains','297'],['classes','✧','Классы и умения','Classes & skills','160'],['mechanics','⚙','Услуги и механики','Services & mechanics','']];
function render(){const r=route(),active=r.view==='location'?'world':r.view==='chain'?'quests':r.view==='class'?'classes':r.view;document.documentElement.lang=lang;$('#nav').innerHTML=navItems.map(([id,symbol,ru,en,c])=>`<a href="#${id}" class="${active===id?'active':''}" ${active===id?'aria-current="page"':''}><span class="nav-symbol" aria-hidden="true">${symbol}</span><span>${t(ru,en)}</span>${c?`<span class="nav-count">${c}</span>`:''}</a>`).join('');$('#ru').classList.toggle('active',lang==='ru');$('#en').classList.toggle('active',lang==='en');$('#sidebar-note').textContent=t('Истории и механики, сохранённые в оригинальном клиенте.','Stories and mechanics preserved in the original client.');$('#source-button').textContent=t('Источники и достоверность','Sources & evidence');$('#footer').innerHTML=`<span>MONATO ESPRIT · ATLAS</span><span>${t('Обновлено 05.10.2026 · русский / английский','Updated 05 Oct 2026 · Russian / English')}</span>`;$('#global-search').placeholder=t('Найти в атласе…','Search the atlas…');$('#global-search').setAttribute('aria-label',t('Поиск по атласу','Search the atlas'));const nav=navItems.find(x=>x[0]===active);$('#breadcrumbs').innerHTML=`ATLAS <span>${nav?t(nav[2],nav[3]):t(r.view==='sources'?'Источники':'Поиск',r.view==='sources'?'Sources':'Search')}</span>`;let html='';if(r.view==='home')html=home();else if(r.view==='wings')html=wingsPage();else if(r.view==='items')html=itemsPage();else if(r.view==='world')html=world();else if(r.view==='location')html=locationPage(r.id,r.query);else if(r.view==='npcs')html=npcDirectory(r.query);else if(r.view==='story')html=storyPage(r.query);else if(r.view==='bestiary'||r.view==='bosses')html=entities('monster',r.view==='bosses');else if(r.view==='quests')html=questsPage();else if(r.view==='chain')html=chainPage(r.id);else if(r.view==='classes')html=classesPage();else if(r.view==='class')html=classPage(r.id);else if(r.view==='mechanics')html=mechanicsPage();else if(r.view==='sources')html=sourcesPage();else if(r.view==='search')html=searchPage(decodeURIComponent(r.id||''));else html=empty('Страница не найдена.','Page not found.');$('#content').innerHTML=html;document.title=(nav?t(nav[2],nav[3]):r.view)+' · Monato Esprit Atlas';}
document.addEventListener('click',e=>{if(e.target.closest('a.skip')){e.preventDefault();$('#content').focus();return}const detailTarget=e.target.closest('[data-detail]');if(detailTarget){detail(detailTarget.dataset.detail,detailTarget.dataset.id);return}const el=e.target.closest('[data-category],[data-set],[data-page],[data-zone-tab],[data-lightbox]');if(el){if(el.dataset.category){category=el.dataset.category;page=1;render()}if(el.dataset.set){classSet=el.dataset.set;render()}if(el.dataset.page){page=Number(el.dataset.page);render();window.scrollTo({top:0,behavior:'smooth'})}if(el.dataset.zoneTab){const r=route();r.query.set('tab',el.dataset.zoneTab);location.hash=`location/${r.id}?${r.query}`}if(el.dataset.lightbox){$('#lightbox-image').src=el.dataset.lightbox;$('#lightbox-image').alt=el.dataset.caption||'';$('#lightbox-caption').textContent=el.dataset.caption||'';$('#lightbox').showModal()}}if(e.target.closest('a[href^="#"]')){if($('#detail').open)$('#detail').close();document.body.classList.remove('menu-open')}});
document.addEventListener('change',e=>{if(e.target.id==='location-filter'||e.target.id==='region-filter'){region=e.target.value;page=1;render()}if(e.target.id==='variant-filter'){const r=route();r.query.set('variant',e.target.value);location.hash=`location/${r.id}?${r.query}`}});
function setLang(next){lang=next;localStorage.setItem('monato-lang',lang);render();if(currentDetail&&$('#detail').open)detail(currentDetail.kind,currentDetail.id)}$('#ru').onclick=()=>setLang('ru');$('#en').onclick=()=>setLang('en');$('#menu').onclick=()=>document.body.classList.toggle('menu-open');$('#source-button').onclick=()=>location.hash='sources';$('#close-detail').onclick=()=>$('#detail').close();$('#close-lightbox').onclick=()=>$('#lightbox').close();for(const dialog of [$('#detail'),$('#lightbox')])dialog.addEventListener('click',e=>{if(e.target===dialog){const rect=dialog.getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom)dialog.close()}});
$('#global-search').addEventListener('input',e=>{clearTimeout(searchTimer);const value=e.target.value;searchTimer=setTimeout(()=>{location.hash='search/'+encodeURIComponent(value)},220)});document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA'].includes(document.activeElement.tagName)&&!$('#detail').open){e.preventDefault();$('#global-search').focus()}if(e.key==='Escape')document.body.classList.remove('menu-open')});
window.addEventListener('hashchange',()=>{const r=route();if(!['location','search'].includes(r.view)){page=1;category='all';region='all'}render();if(r.view!=='search')window.scrollTo({top:0})});render();



function mechanicsPage(){return servicesOverview()+`<details class="mechanics-explanations"><summary>${t('Подробности обучения, боя и восстановления','Tutorial, combat & recovery details')}</summary>${legacyMechanicsPage()}</details>`}
